package com.aritxonly.deadliner.notification

import android.content.Context
import com.aritxonly.deadliner.R
import com.deadliner.domain.habit.HabitGoalWindow
import com.deadliner.platform.NotificationMetadataEntry

/** Native formatting only; counts and goal windows are generated by KMP. */
internal object HabitIslandPresentation {
    fun period(context: Context, entry: NotificationMetadataEntry): String = context.getString(when (entry.habitWindow) {
        HabitGoalWindow.WEEK -> R.string.notification_habit_weekly
        HabitGoalWindow.MONTH -> R.string.notification_habit_monthly
        HabitGoalWindow.LIFETIME -> R.string.notification_habit_lifetime
        else -> R.string.notification_habit_daily
    })
    fun progress(entry: NotificationMetadataEntry): String = "${entry.completedCount ?: 0}/${entry.targetCount ?: 1}"
    fun name(title: String): String {
        val count = title.codePointCount(0, title.length)
        return if (count <= 8) title else title.substring(0, title.offsetByCodePoints(0, 7)) + "…"
    }
}
